import { Component, OnInit } from '@angular/core';
import { CurrentStore } from '@rsApp/modules/store/store.module';

@Component({
  selector: 'weekly-flyer-view',
  templateUrl: './weekly-flyer-view.component.html',
  styleUrls: ['./weekly-flyer-view.component.css'],
})
export class WeeklyFlyerViewComponent implements OnInit {
  public store: any;
  public magDigitalCircularInnerHtml: string = '';

  constructor(private cStore: CurrentStore) {}

  async ngOnInit() {
    this.store = await this.cStore.getStore();
    this.magDigitalCircularInnerHtml = `<mag-digital-circular store-code="${this.store?.StoreCode}"></mag-digital-circular>`;
  }
}
