import { Component, OnInit } from '@angular/core';
import { Router } from '@angular/router';
import { NavController } from '@ionic/angular';

@Component({
  selector: 'weekly-all-ads',
  templateUrl: './weekly-all-ads.component.html',
  styleUrls: ['./weekly-all-ads.component.scss'],
})
export class WeeklyAllAdsComponent implements OnInit {
  public slug: string;

  constructor(
    public router: Router,
    public navCtrl: NavController
  ) {}

  ngOnInit() {
    this.slug = this.router.url.split('?')[0];
  }

  backToHome() {
    this.navCtrl.navigateRoot('/tabs/home', { replaceUrl: true });
  }
}
