import { ChangeDetectorRef, Component, ElementRef, OnDestroy, OnInit, ViewChild } from '@angular/core';
import { Router } from '@angular/router';
import { NavController } from '@ionic/angular';
import { EnumMagFulfillmentManagementRenderType, EnumMagWeeklyadTabOption } from '@rsApp/core/enum';
import { RouteTrackerService } from '@rsApp/modules/utils/providers/route-tracker.service';
import { Subject, combineLatest, takeUntil, timer } from 'rxjs';
import { AppSettings } from '@rsApp/modules/utils/providers/app-setting';
import { DEFAULT_LOCALE, LOCAL_LOCALE_KEY } from '@rsApp/modules/utils/constants/constants';
import { Storage } from '@ionic/storage';

interface IWeeklyAdTab {
  id: string;
  label: string;
}

@Component({
  selector: 'weely-ad-page',
  templateUrl: './weekly-ad-page.component.html',
  styleUrls: ['./weekly-ad-page.component.scss'],
})
export class WeeklyAdPageComponent implements OnInit, OnDestroy {
  @ViewChild('container') containerElement!: ElementRef;

  public enumTabsOptionType = EnumMagWeeklyadTabOption;
  public activeTab: IWeeklyAdTab;
  public isShoppingList: boolean = false;
  public enabledPage: boolean = true;
  public enabledSubscribeBanner: boolean = false;
  public loaded: boolean = false;
  public loadedWidget: boolean = false;
  public loadingSkeleton: boolean = true;
  public dataTabs: IWeeklyAdTab[];

  private destroy$ = new Subject<boolean>();
  private clearInterval;

  constructor(
    public router: Router,
    public navCtrl: NavController,
    private routeTracker: RouteTrackerService,
    private appSettings: AppSettings,
    private storage: Storage,
    private cdr: ChangeDetectorRef
  ) {}

  async ngOnInit() {
    const currentLocale = (await this.storage.get(LOCAL_LOCALE_KEY)) || DEFAULT_LOCALE;

    combineLatest([
      this.appSettings.getSettingValue('digital_circular_support'),
      this.appSettings.getSettingValue('digital_circular_page_navigation_support'),
      this.appSettings.getSettingValue('subscribe_now_banner_support'),
    ])
      .pipe(takeUntil(this.destroy$))
      .subscribe(([digitalCircular, navigationSupport, subscribeNowBanner]) => {
        const configTabs = JSON.parse(navigationSupport);
        // 1. Set digital circular enabled flag
        this.enabledPage = digitalCircular?.toLowerCase() === 'true';
        this.enabledSubscribeBanner = subscribeNowBanner?.toLowerCase() === 'true';

        // 2. Mapping data tabs
        this.dataTabs =
          configTabs &&
          configTabs.map((config) => ({
            id: config?.Id,
            label: config?.Title?.[currentLocale],
          }));

        // 3. Set active tab
        if (this.dataTabs?.length) {
          const path = this.router.url.split('/').pop() || EnumMagWeeklyadTabOption.FlyerView;
          this.activeTab = this.dataTabs.find((tab) => tab.id == path);
        }

        this.loaded = true;
        this.loadedWidget = true;
        this.showLoadingSkeleton();
      });

    this.routeTracker
      .getRenderType()
      .pipe(takeUntil(this.destroy$))
      .subscribe((value) => {
        this.isShoppingList = value === EnumMagFulfillmentManagementRenderType.ShoppingList;
        this.loadedWidget = false;
        this.cdr.detectChanges();
        this.loadedWidget = true;
        const path = this.router.url.split('/').pop() || EnumMagWeeklyadTabOption.FlyerView;
        if (path === EnumMagWeeklyadTabOption.FlyerView) {
          this.activeTab = this.dataTabs.find((tab) => tab.id == path);
        }
        this.showLoadingSkeleton();

        this.clearInterval = setInterval(() => {
          window.scrollTo(0, window.scrollY + 1);
        }, 3000);
      });

    window.addEventListener(
      'message',
      (event) => {
        if (event.origin !== window.location.origin) return;

        if (event.data.action == 'MagFlipLoadCompleted') {
          this.loadingSkeleton = false;
          this.cdr.detectChanges();
        }
      },
      false
    );
  }

  ngOnDestroy() {
    this.destroy$.next(true);
    this.destroy$.complete();
    if (this.clearInterval) {
      clearInterval(this.clearInterval);
    }
  }

  backToHome() {
    this.navCtrl.navigateRoot('/tabs/home', { replaceUrl: true });
  }

  selectedChanged(event) {
    this.loadedWidget = false;
    this.activeTab = event.detail;
    window.history.replaceState({}, '', '/tabs/weekly-ad');
    this.navCtrl.navigateForward(`/tabs/weekly-ad/${event.detail?.id || EnumMagWeeklyadTabOption.FlyerView}`);
    this.containerElement?.nativeElement?.scrollIntoView({ behavior: 'smooth', block: 'start' });
  }

  showLoadingSkeleton() {
    this.loadingSkeleton = true;
    if (this.activeTab.id == this.enumTabsOptionType?.FlyerView) return;

    timer(3000)
      .pipe(takeUntil(this.destroy$))
      .subscribe(() => (this.loadingSkeleton = false));
  }
}
