import { NgModule } from '@angular/core';
import { RouterModule, Routes } from '@angular/router';
import { WeeklyAdPageComponent } from './pages/weekly-ad-page/weekly-ad-page.component';
import { WeeklyAdModule } from './weekly-ad.module';
import { WeeklyAllAdsComponent } from './pages/weekly-all-ads/weekly-all-ads.component';
import { WeeklyProductViewComponent } from './pages/weekly-product-view/weekly-product-view.component';
import { WeeklyFlyerViewComponent } from './pages/weekly-flyer-view/weekly-flyer-view.component';

const routes: Routes = [
  {
    path: '',
    component: WeeklyAdPageComponent,
    children: [
      { path: '', redirectTo: 'flyer-view', pathMatch: 'full' },
      { path: 'flyer-view', component: WeeklyFlyerViewComponent },
      { path: 'product-view', component: WeeklyProductViewComponent },
      { path: 'all-ads', component: WeeklyAllAdsComponent },
    ],
  },
];

@NgModule({
  imports: [RouterModule.forChild(routes), WeeklyAdModule],
  declarations: [],
})
export class WeeklyAdRoutingModule {}
